// 关卡 04 · 账单是二次增长的
//
// docs/00-loop.md 里那次真实运行:六轮,最后消息数组是 1192 tokens。
// 这一关把「你被计了多少费」算出来,并且把它和「这段对话有多大」分开。
package main

import "fmt"

func main() {
	history := 0 // 消息数组现在有多大
	billed := 0  // 到目前为止一共付了多少

	fmt.Println("turn  what it did                   prompt")
	fmt.Println("----  ----------------------------  ------")

	for _, t := range turns {
		history += t.Grew

		// 这一轮的账单
		[[1]]

		fmt.Printf("%4d  %-28s  %6d\n", t.N, t.What, [[2]])
	}

	fmt.Println()
	fmt.Printf("最终会话大小: %5d tokens\n", history)
	fmt.Printf("实际账单:     %5d tokens\n", billed)
	fmt.Printf("倍数:         %5.1fx\n", [[3]])
}

package main

// docs/00-loop.md 里那次真实运行:找 bug、读文件、跑一遍、打补丁、再读、验证。
// Grew 是这一轮往消息数组里添了多少 token。
type turn struct {
	N    int
	What string
	Grew int
}

var turns = []turn{
	{1, "ls -la", 429},
	{2, "cat README.md; cat stats.py", 184},
	{3, "python stats.py -> traceback", 124},
	{4, "sed -i ... (patch)", 195},
	{5, "cat stats.py", 147},
	{6, "python stats.py -> clean", 113},
}
